import {ToolRegistry} from './registry.js';
import {vi} from 'vitest';

describe('ToolRegistry', () => {
  it('registers a tool requiring a location string, calls execute with {}, and asserts the returned result names location as required and the executor\'s call count is 0', async () => {
    const registry = new ToolRegistry();
    const execute = vi.fn().mockResolvedValue('success');
    registry.register({
      name: 'get_weather',
      description: 'Get weather',
      inputSchema: { type: 'object', required: ['location'], properties: { location: { type: 'string' } } }
    }, execute);

    const response = await registry.execute('get_weather', {});
    expect(response.result).toMatch(/location/);
    expect(response.result).toMatch(/required/);
    expect(execute).toHaveBeenCalledTimes(0);
  });

  it('passes valid input with an unlisted extra property to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    const execute = vi.fn().mockResolvedValue('success');
    registry.register({
      name: 'get_weather',
      description: 'Get weather',
      inputSchema: { type: 'object', required: ['location'], properties: { location: { type: 'string' } } }
    }, execute);

    await registry.execute('get_weather', { location: 'Paris', extra: 'ignored' });
    expect(execute).toHaveBeenCalledTimes(1);
    expect(execute).toHaveBeenCalledWith({ location: 'Paris', extra: 'ignored' }, undefined);
  });

  it('throws Unknown tool: <name> for an unregistered name, unchanged', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('missing', {})).rejects.toThrow('Unknown tool: missing');
  });

  it('validates function-valued tool definition whose returned schema differs between calls against the schema current at that call, not a stale cached one', async () => {
    const registry = new ToolRegistry();
    const execute = vi.fn().mockResolvedValue('success');
    let useSchemaA = true;
    const schemaA = { type: 'object', required: ['propA'], properties: { propA: { type: 'string' } } };
    const schemaB = { type: 'object', required: ['propB'], properties: { propB: { type: 'string' } } };

    registry.register(() => ({
      name: 'dynamic_tool',
      description: 'Dynamic schema',
      inputSchema: useSchemaA ? schemaA : schemaB,
    }), execute);

    // Call 1: expects propA
    await registry.execute('dynamic_tool', { propA: 'val' });
    expect(execute).toHaveBeenCalledTimes(1);

    // Call 2: expects propA, missing
    const res2 = await registry.execute('dynamic_tool', { propB: 'val' });
    expect(res2.result).toMatch(/propA/);

    useSchemaA = false; // switch to schemaB
    // Call 3: expects propB
    await registry.execute('dynamic_tool', { propB: 'val' });
    expect(execute).toHaveBeenCalledTimes(2);

    // Call 4: expects propB, missing
    const res4 = await registry.execute('dynamic_tool', { propA: 'val' });
    expect(res4.result).toMatch(/propB/);
  });

  it('compiles a static tool\'s schema once across ten execute calls', async () => {
    const registry = new ToolRegistry();
    const execute = vi.fn().mockResolvedValue('success');
    registry.register({
      name: 'static_tool',
      description: 'Static',
      inputSchema: { type: 'object', required: ['prop'], properties: { prop: { type: 'string' } } }
    }, execute);

    const ajvCompileSpy = vi.spyOn((registry as any).ajv, 'compile');

    for (let i = 0; i < 10; i++) {
      await registry.execute('static_tool', { prop: 'val' });
    }
    expect(execute).toHaveBeenCalledTimes(10);
    expect(ajvCompileSpy).toHaveBeenCalledTimes(0); // already compiled in register
  });
});
